// Keys generated by the installation itself when no secrets are set.
import { env } from "cloudflare:workers";
import { describe, expect, it } from "vitest";
import { ensureInstanceSecrets } from "../worker/lib/instance-secrets";
import { EXPORT_TABLES } from "../worker/routes/season";
import { rows } from "./helpers";

describe("Erzeugte Schlüssel", () => {
  it("fehlende Secrets werden einmal erzeugt und bleiben gleich, gesetzte haben Vorrang", async () => {
    const a = { DB: env.DB, APP_SECRET: "", VAPID_PUBLIC_KEY: undefined, VAPID_PRIVATE_KEY: undefined } as unknown as Env;
    await ensureInstanceSecrets(a);
    expect(a.APP_SECRET.length).toBeGreaterThanOrEqual(32);
    expect(a.VAPID_PUBLIC_KEY).toMatch(/^[A-Za-z0-9_-]{87}$/);
    expect(a.VAPID_PRIVATE_KEY).toMatch(/^[A-Za-z0-9_-]{43}$/);
    const b = { DB: env.DB, APP_SECRET: "set-in-cloudflare-0123456789", VAPID_PUBLIC_KEY: undefined, VAPID_PRIVATE_KEY: undefined } as unknown as Env;
    await ensureInstanceSecrets(b);
    expect(b.APP_SECRET).toBe("set-in-cloudflare-0123456789");
    expect(b.VAPID_PUBLIC_KEY).toBe(a.VAPID_PUBLIC_KEY);
    expect(await rows("SELECT key FROM instance_secrets")).toEqual([{ key: "generated" }]);
    expect(EXPORT_TABLES).not.toContain("instance_secrets");
  });
});
